const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{
        .name = "kvhttp",
        .root_module = root_module,
    });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    const run_step = b.step("run", "Run the server");
    run_step.dependOn(&run_cmd.step);

    const unit_tests = b.addTest(.{ .root_module = root_module });
    const test_step = b.step("test", "Run unit tests");
    test_step.dependOn(&b.addRunArtifact(unit_tests).step);
}

//! Thread-safe in-memory key-value store.
//!
//! Values are immutable, reference-counted `Blob`s: readers take a reference
//! under the lock and release it after transmitting, so the lock is never
//! held during network I/O.
const Store = @This();

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged(*Blob) = .empty,

pub const key_max = 64;

pub const Blob = struct {
    refs: std.atomic.Value(usize),
    data: []const u8,

    fn create(gpa: Allocator, bytes: []const u8) Allocator.Error!*Blob {
        const blob = try gpa.create(Blob);
        errdefer gpa.destroy(blob);
        blob.* = .{ .refs = .init(1), .data = try gpa.dupe(u8, bytes) };
        return blob;
    }

    fn retain(blob: *Blob) void {
        _ = blob.refs.fetchAdd(1, .monotonic);
    }
};

pub const PutResult = enum { created, replaced };

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(store: *Store) void {
    var it = store.map.iterator();
    while (it.next()) |entry| {
        store.gpa.free(entry.key_ptr.*);
        store.release(entry.value_ptr.*);
    }
    store.map.deinit(store.gpa);
    store.* = undefined;
}

/// Drops a reference obtained from `get`.
pub fn release(store: *Store, blob: *Blob) void {
    if (blob.refs.fetchSub(1, .acq_rel) == 1) {
        store.gpa.free(blob.data);
        store.gpa.destroy(blob);
    }
}

/// Stores a copy of `value` under a copy of `key`.
pub fn put(store: *Store, io: Io, key: []const u8, value: []const u8) Allocator.Error!PutResult {
    const blob = try Blob.create(store.gpa, value);
    errdefer store.release(blob);

    store.lock.lockUncancelable(io);
    const gop = gop: {
        errdefer store.lock.unlock(io);
        const gop = try store.map.getOrPut(store.gpa, key);
        if (!gop.found_existing) {
            gop.key_ptr.* = store.gpa.dupe(u8, key) catch |err| {
                store.map.removeByPtr(gop.key_ptr);
                return err;
            };
        }
        break :gop gop;
    };
    const old = if (gop.found_existing) gop.value_ptr.* else null;
    gop.value_ptr.* = blob;
    store.lock.unlock(io);

    if (old) |b| {
        store.release(b);
        return .replaced;
    }
    return .created;
}

/// Returns a new reference to the value (drop it with `release`), or null.
pub fn get(store: *Store, io: Io, key: []const u8) ?*Blob {
    store.lock.lockSharedUncancelable(io);
    defer store.lock.unlockShared(io);
    const blob = store.map.get(key) orelse return null;
    blob.retain();
    return blob;
}

/// Returns true if the key existed and was removed.
pub fn delete(store: *Store, io: Io, key: []const u8) bool {
    store.lock.lockUncancelable(io);
    const removed = store.map.fetchRemove(key);
    store.lock.unlock(io);

    const kv = removed orelse return false;
    store.gpa.free(kv.key);
    store.release(kv.value);
    return true;
}

/// Returns every key, sorted ascending by byte value. All memory, including
/// the key strings, is owned by `arena`.
pub fn keys(store: *Store, io: Io, arena: Allocator) Allocator.Error![]const []const u8 {
    const list = list: {
        store.lock.lockSharedUncancelable(io);
        defer store.lock.unlockShared(io);
        const list = try arena.alloc([]const u8, store.map.count());
        var it = store.map.keyIterator();
        for (list) |*slot| slot.* = try arena.dupe(u8, it.next().?.*);
        break :list list;
    };
    std.mem.sort([]const u8, list, {}, lessThan);
    return list;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.lessThan(u8, a, b);
}

test "put, get, replace, delete" {
    const io = std.testing.io;
    var store: Store = .init(std.testing.allocator);
    defer store.deinit();

    try std.testing.expectEqual(.created, try store.put(io, "a", "hello"));
    try std.testing.expectEqual(.replaced, try store.put(io, "a", "world"));

    const blob = store.get(io, "a").?;
    defer store.release(blob);
    try std.testing.expectEqualStrings("world", blob.data);

    try std.testing.expect(store.delete(io, "a"));
    try std.testing.expect(!store.delete(io, "a"));
    try std.testing.expectEqual(null, store.get(io, "a"));
    // The reference taken before deletion stays valid.
    try std.testing.expectEqualStrings("world", blob.data);
}

test "keys are sorted" {
    const io = std.testing.io;
    var store: Store = .init(std.testing.allocator);
    defer store.deinit();
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();

    for ([_][]const u8{ "b", "a", "_", "B", "c-1" }) |k| _ = try store.put(io, k, "");
    const list = try store.keys(io, arena.allocator());
    try std.testing.expectEqual(5, list.len);
    const want = [_][]const u8{ "B", "_", "a", "b", "c-1" };
    for (want, list) |w, got| try std.testing.expectEqualStrings(w, got);
}

//! Minimal HTTP/1.1 request parsing and response writing.
const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

pub const Status = std.http.Status;

/// Largest accepted request head (request line plus headers).
pub const head_max = 16 * 1024;

const chunk_line_max = 255;

pub const Request = struct {
    method: []const u8,
    target: []const u8,
    /// Empty when the request has no body.
    body: []const u8,
};

/// Failures that are answered with an error status (see `statusFor`).
pub const RequestError = error{
    BadRequest,
    ContentTooLarge,
    ExpectationFailed,
    HeaderFieldsTooLarge,
    NotImplemented,
    VersionNotSupported,
    OutOfMemory,
};

/// The peer went away or timed out; no response should be attempted.
pub const ReadError = RequestError || error{ConnectionClosed};

pub fn statusFor(err: RequestError) Status {
    return switch (err) {
        error.BadRequest => .bad_request,
        error.ContentTooLarge => .payload_too_large,
        error.ExpectationFailed => .expectation_failed,
        error.HeaderFieldsTooLarge => .request_header_fields_too_large,
        error.NotImplemented => .not_implemented,
        error.VersionNotSupported => .http_version_not_supported,
        error.OutOfMemory => .internal_server_error,
    };
}

const Framing = struct {
    content_length: ?u64 = null,
    chunked: bool = false,
    expect_continue: bool = false,
};

/// Reads one request, accepting bodies up to `max_body` bytes. `in` must have
/// a buffer of at least `head_max` bytes. The interim `100 Continue` response
/// is written to `out` when the client asks for it. Everything returned is
/// allocated in `arena`.
pub fn readRequest(arena: Allocator, in: *Io.Reader, out: *Io.Writer, max_body: usize) ReadError!Request {
    std.debug.assert(in.buffer.len >= head_max);

    // The head is copied out of the reader buffer, which reading the body reuses.
    const head_len = try fillHead(in);
    const head = try arena.dupe(u8, in.buffered()[0..head_len]);
    in.toss(head_len);

    var lines = std.mem.splitScalar(u8, head, '\n');
    var request = try parseRequestLine(trimCr(lines.first()));
    const framing = try parseHeaders(&lines);

    if (framing.content_length) |len| if (len > max_body) return error.ContentTooLarge;
    if (framing.expect_continue and (framing.chunked or (framing.content_length orelse 0) > 0)) {
        out.writeAll("HTTP/1.1 100 Continue\r\n\r\n") catch return error.ConnectionClosed;
        out.flush() catch return error.ConnectionClosed;
    }

    if (framing.chunked) {
        request.body = try readChunked(arena, in, max_body);
    } else if (framing.content_length) |len| {
        const body = try arena.alloc(u8, @intCast(len));
        in.readSliceAll(body) catch return error.ConnectionClosed;
        request.body = body;
    }
    return request;
}

/// Buffers bytes until the blank line ending the head; returns its length.
fn fillHead(in: *Io.Reader) ReadError!usize {
    var scanned: usize = 0;
    while (true) {
        const buf = in.buffered();
        if (findHeadEnd(buf, scanned)) |end| return end;
        // Resume where the previous scan stopped, allowing for a split "\n\r\n".
        scanned = buf.len -| 2;
        if (buf.len >= head_max) return error.HeaderFieldsTooLarge;
        in.fillMore() catch return error.ConnectionClosed;
    }
}

/// Returns the offset just past the first "\n\n" or "\n\r\n" at or after `from`.
fn findHeadEnd(buf: []const u8, from: usize) ?usize {
    var i = from;
    while (std.mem.indexOfScalarPos(u8, buf, i, '\n')) |nl| : (i = nl + 1) {
        const rest = buf[nl + 1 ..];
        if (std.mem.startsWith(u8, rest, "\n")) return nl + 2;
        if (std.mem.startsWith(u8, rest, "\r\n")) return nl + 3;
    }
    return null;
}

fn parseRequestLine(line: []const u8) RequestError!Request {
    var parts = std.mem.splitScalar(u8, line, ' ');
    const method = parts.first();
    const target = parts.next() orelse return error.BadRequest;
    const version = parts.rest();
    if (parts.index == null) return error.BadRequest;

    if (method.len == 0 or target.len == 0) return error.BadRequest;
    if (!isToken(method)) return error.BadRequest;
    if (version.len != "HTTP/1.x".len or !std.mem.startsWith(u8, version, "HTTP/1.") or
        !std.ascii.isDigit(version[7]))
    {
        return if (std.mem.startsWith(u8, version, "HTTP/")) error.VersionNotSupported else error.BadRequest;
    }
    return .{ .method = method, .target = target, .body = "" };
}

fn parseHeaders(lines: *std.mem.SplitIterator(u8, .scalar)) RequestError!Framing {
    var framing: Framing = .{};
    while (lines.next()) |raw| {
        const line = trimCr(raw);
        if (line.len == 0) break;

        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.BadRequest;
        const name = line[0..colon];
        if (name.len == 0 or !isToken(name)) return error.BadRequest;
        const value = std.mem.trim(u8, line[colon + 1 ..], " \t");

        if (std.ascii.eqlIgnoreCase(name, "Content-Length")) {
            const len = parseUnsigned(value, 10) catch return error.BadRequest;
            if (framing.content_length) |prev| if (prev != len) return error.BadRequest;
            framing.content_length = len;
        } else if (std.ascii.eqlIgnoreCase(name, "Transfer-Encoding")) {
            if (!std.ascii.eqlIgnoreCase(value, "chunked")) return error.NotImplemented;
            framing.chunked = true;
        } else if (std.ascii.eqlIgnoreCase(name, "Expect")) {
            if (!std.ascii.eqlIgnoreCase(value, "100-continue")) return error.ExpectationFailed;
            framing.expect_continue = true;
        }
    }
    if (framing.chunked and framing.content_length != null) return error.BadRequest;
    return framing;
}

fn readChunked(arena: Allocator, in: *Io.Reader, max_body: usize) ReadError![]const u8 {
    var body: std.ArrayList(u8) = .empty;
    while (true) {
        const line = try readLine(in);
        const spec = std.mem.trim(u8, line[0 .. std.mem.indexOfScalar(u8, line, ';') orelse line.len], " \t");
        if (spec.len == 0) return error.BadRequest;
        const size = parseUnsigned(spec, 16) catch |err| return switch (err) {
            error.Overflow => error.ContentTooLarge,
            error.InvalidCharacter => error.BadRequest,
        };
        if (size == 0) break;
        if (size > max_body - body.items.len) return error.ContentTooLarge;

        const dest = try body.addManyAsSlice(arena, @intCast(size));
        in.readSliceAll(dest) catch return error.ConnectionClosed;
        if ((try readLine(in)).len != 0) return error.BadRequest;
    }
    // Trailer section: skip until the blank line.
    while ((try readLine(in)).len != 0) {}
    return body.items;
}

/// Reads one LF-terminated line, without the line terminator.
fn readLine(in: *Io.Reader) ReadError![]const u8 {
    const raw = in.takeDelimiterInclusive('\n') catch |err| return switch (err) {
        error.StreamTooLong => error.BadRequest,
        error.EndOfStream, error.ReadFailed => error.ConnectionClosed,
    };
    const line = raw[0 .. raw.len - 1];
    if (line.len > chunk_line_max) return error.BadRequest;
    return trimCr(line);
}

fn trimCr(line: []const u8) []const u8 {
    return if (std.mem.endsWith(u8, line, "\r")) line[0 .. line.len - 1] else line;
}

/// Parses a non-empty run of digits. Unlike `std.fmt.parseUnsigned`, signs
/// and `_` separators are rejected, as HTTP requires.
fn parseUnsigned(s: []const u8, comptime base: u8) error{ InvalidCharacter, Overflow }!u64 {
    if (s.len == 0) return error.InvalidCharacter;
    var v: u64 = 0;
    for (s) |c| {
        const digit = try std.fmt.charToDigit(c, base);
        v = try std.math.mul(u64, v, base);
        v = try std.math.add(u64, v, digit);
    }
    return v;
}

fn isToken(s: []const u8) bool {
    for (s) |c| {
        if (std.ascii.isAlphanumeric(c)) continue;
        if (std.mem.indexOfScalar(u8, "!#$%&'*+-.^_`|~", c) == null) return false;
    }
    return true;
}

/// Writes a complete response with Content-Length and `Connection: close`.
pub fn respond(out: *Io.Writer, status: Status, content_type: ?[]const u8, body: []const u8) Io.Writer.Error!void {
    try out.print("HTTP/1.1 {d} {s}\r\n", .{ @intFromEnum(status), status.phrase() orelse "Unknown" });
    if (content_type) |ct| try out.print("Content-Type: {s}\r\n", .{ct});
    try out.print("Content-Length: {d}\r\nConnection: close\r\n\r\n", .{body.len});
    try out.writeAll(body);
    try out.flush();
}

// ---------- tests ----------

const testing = std.testing;

fn parseFixed(arena: Allocator, raw: []const u8) ReadError!Request {
    var buf: [head_max]u8 = undefined;
    @memcpy(buf[0..raw.len], raw);
    var in: Io.Reader = .fixed(buf[0..raw.len]);
    in.buffer = &buf; // Give the reader its full capacity, as a socket reader would have.
    var discard: Io.Writer.Discarding = .init(&.{});
    return readRequest(arena, &in, &discard.writer, 1024);
}

test "parses a request with a Content-Length body" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const req = try parseFixed(arena.allocator(), "PUT /kv/a HTTP/1.1\r\nHost: x\r\ncontent-length: 5\r\n\r\nhello");
    try testing.expectEqualStrings("PUT", req.method);
    try testing.expectEqualStrings("/kv/a", req.target);
    try testing.expectEqualStrings("hello", req.body);
}

test "parses a chunked body" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const req = try parseFixed(arena.allocator(), "PUT /kv/a HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n" ++
        "3;ext=1\r\nhel\r\n2\r\nlo\r\n0\r\nTrailer: x\r\n\r\n");
    try testing.expectEqualStrings("hello", req.body);
}

test "rejects malformed requests" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try testing.expectError(error.BadRequest, parseFixed(a, "GET\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseFixed(a, "GET / HTTP/1.1\r\nBad Header: x\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseFixed(a, "GET / HTTP/1.1\r\nContent-Length: +1\r\n\r\n"));
    try testing.expectError(error.VersionNotSupported, parseFixed(a, "GET / HTTP/2.0\r\n\r\n"));
    try testing.expectError(error.ContentTooLarge, parseFixed(a, "PUT / HTTP/1.1\r\nContent-Length: 1025\r\n\r\n"));
    try testing.expectError(error.NotImplemented, parseFixed(a, "PUT / HTTP/1.1\r\nTransfer-Encoding: gzip\r\n\r\n"));
    try testing.expectError(error.ConnectionClosed, parseFixed(a, "PUT / HTTP/1.1\r\nContent-Length: 9\r\n\r\nabc"));
}

test "findHeadEnd accepts bare LF" {
    try testing.expectEqual(@as(?usize, 7), findHeadEnd("GET /\n\nbody", 0));
    try testing.expectEqual(@as(?usize, 9), findHeadEnd("GET /\r\n\r\nbody", 0));
    try testing.expectEqual(@as(?usize, null), findHeadEnd("GET /\r\n", 0));
}

//! kvhttp: an HTTP/1.1 in-memory key-value server.
//! Usage: ./app <port>  (listens on 127.0.0.1)
const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const net = Io.net;

const http = @import("http.zig");
const routes = @import("routes.zig");
const Store = @import("Store.zig");

const max_value = 1024 * 1024;
/// Upper bound on a whole request/response exchange.
const io_timeout: Io.Duration = .fromSeconds(30);
/// How long to drain unread request bytes after responding.
const linger_timeout: Io.Duration = .fromMilliseconds(500);
const linger_max_bytes = 4 * max_value;

const log = std.log.scoped(.kvhttp);

const Server = struct {
    io: Io,
    gpa: Allocator,
    store: Store,

    fn serveConnection(server: *Server, stream: net.Stream) void {
        const io = server.io;
        defer stream.close(io);

        var arena_state: std.heap.ArenaAllocator = .init(server.gpa);
        defer arena_state.deinit();

        var in_buf: [http.head_max]u8 = undefined;
        var out_buf: [1024]u8 = undefined;
        var reader = stream.reader(io, &in_buf);
        var writer = stream.writer(io, &out_buf);

        const responded = responded: {
            var watchdog = Watchdog.start(io, stream, io_timeout);
            defer watchdog.stop(io);
            break :responded server.exchange(arena_state.allocator(), &reader.interface, &writer.interface);
        };
        if (responded) lingeringClose(io, stream, &reader.interface);
    }

    /// Reads one request and answers it. Returns false when the peer went
    /// away before a response could be attempted.
    fn exchange(server: *Server, arena: Allocator, in: *Io.Reader, out: *Io.Writer) bool {
        const req = http.readRequest(arena, in, out, max_value) catch |err| switch (err) {
            error.ConnectionClosed => return false,
            else => |e| {
                http.respond(out, http.statusFor(e), null, "") catch {};
                return true;
            },
        };
        const res = routes.handle(&server.store, server.io, arena, req) catch
            routes.Response{ .status = .internal_server_error };
        defer if (res.blob) |blob| server.store.release(blob);
        http.respond(out, res.status, res.content_type, res.body) catch {};
        return true;
    }
};

/// Shuts a connection down once a timeout elapses, unblocking any pending
/// read or write on it.
const Watchdog = struct {
    future: ?Io.Future(Io.Cancelable!void),

    fn start(io: Io, stream: net.Stream, timeout: Io.Duration) Watchdog {
        const future = io.concurrent(expire, .{ io, stream, timeout }) catch |err| {
            log.warn("connection runs without a timeout: {t}", .{err});
            return .{ .future = null };
        };
        return .{ .future = future };
    }

    fn stop(w: *Watchdog, io: Io) void {
        if (w.future) |*f| f.cancel(io) catch {};
    }

    fn expire(io: Io, stream: net.Stream, timeout: Io.Duration) Io.Cancelable!void {
        try io.sleep(timeout, .awake);
        stream.shutdown(io, .both) catch {};
    }
};

/// Half-closes and drains, so unread request bytes do not turn our close into
/// a RST that could destroy the response before the client reads it.
fn lingeringClose(io: Io, stream: net.Stream, in: *Io.Reader) void {
    stream.shutdown(io, .send) catch return;
    var watchdog = Watchdog.start(io, stream, linger_timeout);
    defer watchdog.stop(io);
    _ = in.discardShort(linger_max_bytes) catch {};
}

fn rejectBusy(io: Io, stream: net.Stream) void {
    defer stream.close(io);
    var out_buf: [256]u8 = undefined;
    var writer = stream.writer(io, &out_buf);
    http.respond(&writer.interface, .internal_server_error, null, "") catch {};
}

pub fn main(init: std.process.Init) !u8 {
    const io = init.io;

    var args = init.minimal.args.iterate();
    const argv0 = args.next() orelse "app";
    const port_arg = args.next();
    const port = if (port_arg) |arg| std.fmt.parseInt(u16, arg, 10) catch 0 else 0;
    if (port == 0 or args.next() != null) {
        std.debug.print("usage: {s} <port>\n", .{argv0});
        return 2;
    }

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var listener = address.listen(io, .{ .reuse_address = true }) catch |err| {
        log.err("cannot listen on 127.0.0.1:{d}: {t}", .{ port, err });
        return 1;
    };
    defer listener.deinit(io);

    var server: Server = .{ .io = io, .gpa = init.gpa, .store = .init(init.gpa) };
    defer server.store.deinit();

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| switch (err) {
            error.ConnectionAborted => continue,
            error.ProcessFdQuotaExceeded,
            error.SystemFdQuotaExceeded,
            error.SystemResources,
            => {
                // Resource exhaustion: back off briefly instead of spinning.
                try io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
            else => |e| {
                log.err("accept failed: {t}", .{e});
                return 1;
            },
        };
        connections.concurrent(io, Server.serveConnection, .{ &server, stream }) catch {
            rejectBusy(io, stream);
        };
    }
}

test {
    _ = http;
    _ = routes;
    _ = Store;
}

//! Maps requests to responses against the store.
const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const http = @import("http.zig");
const Store = @import("Store.zig");

pub const Response = struct {
    status: http.Status,
    content_type: ?[]const u8 = null,
    body: []const u8 = "",
    /// Store reference backing `body`; the caller releases it after sending.
    blob: ?*Store.Blob = null,

    fn empty(status: http.Status) Response {
        return .{ .status = status };
    }
};

/// Everything allocated for the response lives in `arena`.
pub fn handle(store: *Store, io: Io, arena: Allocator, req: http.Request) Allocator.Error!Response {
    const method = std.meta.stringToEnum(std.http.Method, req.method);
    const path = req.target;

    if (std.mem.eql(u8, path, "/health")) {
        if (method != .GET) return .empty(.method_not_allowed);
        return .{ .status = .ok, .content_type = "text/plain", .body = "ok" };
    }
    if (std.mem.eql(u8, path, "/kv")) {
        if (method != .GET) return .empty(.method_not_allowed);
        return .{ .status = .ok, .content_type = "application/json", .body = try listJson(store, io, arena) };
    }
    if (std.mem.startsWith(u8, path, "/kv/")) {
        const key = path["/kv/".len..];
        if (!isValidKey(key)) return .empty(.bad_request);
        return switch (method orelse return .empty(.method_not_allowed)) {
            .GET => if (store.get(io, key)) |blob|
                .{ .status = .ok, .content_type = "application/octet-stream", .body = blob.data, .blob = blob }
            else
                .empty(.not_found),
            .PUT => switch (try store.put(io, key, req.body)) {
                .created => .empty(.created),
                .replaced => .empty(.ok),
            },
            .DELETE => .empty(if (store.delete(io, key)) .no_content else .not_found),
            else => .empty(.method_not_allowed),
        };
    }
    return .empty(.not_found);
}

pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > Store.key_max) return false;
    for (key) |c| {
        if (!std.ascii.isAlphanumeric(c) and c != '_' and c != '-') return false;
    }
    return true;
}

/// Keys are restricted to `[A-Za-z0-9_-]`, so no JSON escaping is needed.
fn listJson(store: *Store, io: Io, arena: Allocator) Allocator.Error![]const u8 {
    const keys = try store.keys(io, arena);
    var len: usize = 2;
    for (keys) |k| len += k.len + 3;

    var json: std.ArrayList(u8) = try .initCapacity(arena, len);
    json.appendAssumeCapacity('[');
    for (keys, 0..) |k, i| {
        if (i != 0) json.appendAssumeCapacity(',');
        json.appendAssumeCapacity('"');
        json.appendSliceAssumeCapacity(k);
        json.appendAssumeCapacity('"');
    }
    json.appendAssumeCapacity(']');
    return json.items;
}

test isValidKey {
    try std.testing.expect(isValidKey("a"));
    try std.testing.expect(isValidKey("A-z_09"));
    try std.testing.expect(isValidKey("k" ** 64));
    try std.testing.expect(!isValidKey(""));
    try std.testing.expect(!isValidKey("k" ** 65));
    try std.testing.expect(!isValidKey("a/b"));
    try std.testing.expect(!isValidKey("bad.key"));
}

test "routing" {
    const io = std.testing.io;
    var store: Store = .init(std.testing.allocator);
    defer store.deinit();
    var arena_state: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const cases = [_]struct { []const u8, []const u8, []const u8, http.Status, []const u8 }{
        .{ "GET", "/health", "", .ok, "ok" },
        .{ "POST", "/health", "", .method_not_allowed, "" },
        .{ "GET", "/nope", "", .not_found, "" },
        .{ "GET", "/kv/", "", .bad_request, "" },
        .{ "GET", "/kv/a/b", "", .bad_request, "" },
        .{ "PUT", "/kv/b", "2", .created, "" },
        .{ "PUT", "/kv/a", "1", .created, "" },
        .{ "PUT", "/kv/a", "one", .ok, "" },
        .{ "GET", "/kv/a", "", .ok, "one" },
        .{ "PATCH", "/kv/a", "", .method_not_allowed, "" },
        .{ "BREW", "/kv/a", "", .method_not_allowed, "" },
        .{ "GET", "/kv", "", .ok, "[\"a\",\"b\"]" },
        .{ "DELETE", "/kv/a", "", .no_content, "" },
        .{ "DELETE", "/kv/a", "", .not_found, "" },
        .{ "GET", "/kv/a", "", .not_found, "" },
        .{ "POST", "/kv", "", .method_not_allowed, "" },
    };
    for (cases) |c| {
        const res = try handle(&store, io, arena, .{ .method = c[0], .target = c[1], .body = c[2] });
        defer if (res.blob) |b| store.release(b);
        try std.testing.expectEqual(c[3], res.status);
        try std.testing.expectEqualStrings(c[4], res.body);
    }
}
